bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
stage=/home/gace/.local/share/gace-create-videobot/rich-collage-077996f4
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 41
test -f "$stage/sql/024_video_rich_offer_receipts.sql" || exit 42
sql64="$(base64 -w0 "$stage/sql/024_video_rich_offer_receipts.sql")"
docker exec -i -e TEST_VIDEO_SQL_B64="$sql64" -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';import pg from 'pg';
const e=process.env;
const p=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,
 database:e.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1});
const c=await p.connect();
try{
 if(e.VIDEOBOT_DB_NAME!=='videobot')throw Error('WRONG_DB');
 const sql=Buffer.from(e.TEST_VIDEO_SQL_B64,'base64').toString('utf8');
 await c.query('BEGIN');
 try {
   await c.query(sql);
   console.log('VIDEO_RICH_MIGRATION_DRYRUN=PASS');
 }catch(error){
   console.log('VIDEO_RICH_MIGRATION_DRYRUN='+JSON.stringify({ok:false,pgcode:error.code??null,constraint:error.constraint??null,detailCode:error.routine??null,message:String(error.message).slice(0,150)}));
   throw error;
 }finally{await c.query('ROLLBACK').catch(()=>{})}
}finally{c.release();await p.end()}
NODE
echo 'RICH_MIGRATION_REAL_DATA_DRYRUN_PASSED'
